(() => {'use strict';let addresses=[],selected=null,draftId=null;
 const keys=['recipient','phone','country','region','city','address','note'];
 const words={buyer:['مركز المشتري','Buyer center'],title:['عناويني','My addresses'],newAddress:['إضافة عنوان','Add address'],editTitle:['بيانات العنوان','Address details'],label:['اسم العنوان','Address label'],recipient:['اسم المستلم','Recipient'],phone:['رقم الهاتف','Phone'],country:['الدولة','Country'],region:['المنطقة','Region'],city:['المدينة','City'],address:['العنوان التفصيلي','Full address'],note:['ملاحظة التوصيل','Delivery note'],save:['حفظ العنوان','Save address'],cancel:['إلغاء','Cancel'],backCart:['العودة للسلة','Back to cart'],edit:['تعديل','Edit'],remove:['حذف','Delete'],confirm:['حذف هذا العنوان المحفوظ؟','Delete this saved address?'],empty:['لم تحفظ عناوين بعد. أضف عنوانك لتستخدمه عند الطلب.','No saved addresses. Add one to use at checkout.']};
 const w=window.BemoWorkspace.create(words,{onReady:()=>w.run(load),onClear:()=>{addresses=[];selected=null;draftId=null;w.$('addressList').replaceChildren();w.$('addressForm').reset();w.$('addressEditor').hidden=true;w.$('newAddress').hidden=true;},onLanguage:()=>{render();w.$('checkoutLink').href=w.url('market.html',{view:'cart'});}}),$=w.$,n=w.node;
 async function load(req){addresses=await req('bemo_list_addresses');$('newAddress').hidden=false;render();}
 function edit(a){selected=a;draftId=a?.id||crypto.randomUUID();$('label').value=a?.label||'';for(const k of keys)$(k).value=a?.delivery[k]||'';$('addressEditor').hidden=false;$('label').focus();}
 function render(){$('addressList').replaceChildren();if(!addresses.length)$('addressList').append(n('p',w.t('empty'),'workspace-empty'));for(const a of addresses){const card=n('article',undefined,'account-card address-card'),actions=n('div',undefined,'address-actions'),editButton=n('button',w.t('edit'),'secondary-button'),remove=n('button',w.t('remove'),'secondary-button');editButton.type=remove.type='button';editButton.addEventListener('click',()=>edit(a));remove.addEventListener('click',()=>{if(card.querySelector('.address-confirm'))return;const prompt=n('div',undefined,'address-confirm'),yes=n('button',w.t('remove'),'primary-button'),no=n('button',w.t('cancel'),'secondary-button');yes.type=no.type='button';yes.addEventListener('click',()=>w.run(async req=>{await req('bemo_delete_address',{address_id:a.id,expected_version:a.version});if(selected?.id===a.id){selected=null;$('addressForm').reset();$('addressEditor').hidden=true;}await load(req);},'saving'));no.addEventListener('click',()=>prompt.remove());prompt.append(n('p',w.t('confirm')),yes,no);card.append(prompt);});actions.append(editButton,remove);card.append(n('h2',a.label),n('p',a.delivery.recipient+'\n'+a.delivery.address+'\n'+[a.delivery.city,a.delivery.region,a.delivery.country].join(' · ')+'\n'+a.delivery.phone),actions);$('addressList').append(card);}}
 $('newAddress').addEventListener('click',()=>{if(w.ready()&&!w.busy())edit(null);});$('cancel').addEventListener('click',()=>{$('addressEditor').hidden=true;$('addressForm').reset();selected=null;draftId=null;});$('addressForm').addEventListener('submit',e=>{e.preventDefault();if(!draftId)return;const delivery={};for(const k of keys)delivery[k]=$(k).value.trim();const args={address_id:draftId,label:$('label').value.trim(),delivery,expected_version:selected?.version||0};w.run(async req=>{await req('bemo_save_address',args);$('addressForm').reset();$('addressEditor').hidden=true;selected=null;draftId=null;await load(req);},'saving');});w.start();
})();
